"""PL-01 step 3: put every ticker on one calendar."""

from collections.abc import Mapping, Sequence

from mdata.types import GapError, Prices, RawRow


def align_calendar(rows: Sequence[RawRow], *, max_gap: int = 5) -> Prices:
    """One calendar from the first date every ticker has a close; gaps take the previous close (DATA-03, DATA-04)."""
    by_ticker = _closes_by_ticker(rows)
    tickers = tuple(sorted(by_ticker))
    dates = _calendar(by_ticker)
    return Prices(
        dates=dates,
        tickers=tickers,
        closes={ticker: _forward_fill(ticker, by_ticker[ticker], dates, max_gap) for ticker in tickers},
    )


def _closes_by_ticker(rows: Sequence[RawRow]) -> dict[str, dict[str, float]]:
    """Each ticker's closes by date, skipping blank cells."""
    by_ticker: dict[str, dict[str, float]] = {}
    for row in rows:
        closes = by_ticker.setdefault(row.ticker, {})
        if row.close is not None:
            closes[row.date] = row.close
    return by_ticker


def _calendar(by_ticker: Mapping[str, Mapping[str, float]]) -> tuple[str, ...]:
    """The dates any ticker has a close, from the first date every ticker has one."""
    if not by_ticker or not all(by_ticker.values()):
        return ()
    start = max(min(closes) for closes in by_ticker.values())
    traded = {day for closes in by_ticker.values() for day in closes}
    return tuple(sorted(day for day in traded if day >= start))


def _forward_fill(ticker: str, closes: Mapping[str, float], dates: Sequence[str], max_gap: int) -> tuple[float, ...]:
    """The ticker's close on each date, a missing date taking the previous close; GapError past `max_gap` in a row."""
    filled: list[float] = []
    missing = 0
    for day in dates:
        if day in closes:
            filled.append(closes[day])
            missing = 0
            continue
        missing += 1
        if missing > max_gap:
            raise GapError(f"{ticker} misses more than {max_gap} dates in a row, through {day}")
        filled.append(filled[-1])
    return tuple(filled)

